import re

LANGS = ("hi", "mr", "gu", "bn", "ta", "te", "kn", "ml")

def _r(*eight):
    return dict(zip(LANGS, eight))

# phrase -> {lang: translation}. Longer phrases are applied first.
P = {}

def add(en, *eight):
    P[en] = _r(*eight)

