_BUILT = {}

def _compile(lang):
    if lang in _BUILT:
        return _BUILT[lang]
    items = sorted((( _norm(en), tr[lang]) for en, tr in P.items() if tr.get(lang)), key=lambda kv: len(kv[0]), reverse=True)
    parts = []
    for en, _tr in items:
        parts.append(r"(?<![A-Za-z0-9'/])" + re.escape(en) + r"(?![A-Za-z0-9'/])")
    rx = re.compile("|".join(parts)) if parts else None
    _BUILT[lang] = (rx, {en: tr for en, tr in items})
    return _BUILT[lang]

