def _unescape(text: str) -> str:
    return _html.unescape(text).replace("\xa0", " ").replace("\u202f", " ")

def _norm(text: str) -> str:
    return (text.replace("\u2019", "'").replace("\u2018", "'")
            .replace("\u201c", '"').replace("\u201d", '"')
            .replace("\xa0", " ").replace("\u202f", " "))

def _glossary(text: str, lang: str) -> str:
    from . import i18n
    if lang not in i18n.MAPS or not re.search(r"[A-Za-z]", text):
        return text
    rx = i18n._term_re(lang)
    return rx.sub(lambda mm: i18n.MAPS[lang][mm.group(1)], text)

_KEEP = re.compile(r"https?://\S+")
_ORD = {"hi": "वाँ", "mr": "वा", "gu": "મું", "bn": "তম", "ta": "ஆம்", "te": "వ", "kn": "ನೇ", "ml": "ആം"}

def _shield(text):
    saved = []
    def sub(m):
        saved.append(m.group(0))
        return f"⟦{len(saved) - 1}⟧"
    return _KEEP.sub(sub, text), saved

def _restore(text, saved):
    if not saved:
        return text
    return re.sub(r"⟦(\d+)⟧", lambda m: saved[int(m.group(1))], text)

def translate_plain(text: str, lang: str) -> str:
    """Replace a whole phrase first, then any remaining known terms.

    A full-sentence conversion is kept. It is not thrown away when a later
    word pass has nothing left to change.
    """
    if lang in (None, "", "en") or not text or not re.search(r"[A-Za-z]", text):
        return text
    original = text
    src = _norm(_unescape(text))
    from .prose_i18n import apply as _apply, exact as _exact
    src = _apply(src, lang)
    stripped = src.strip()
    hit = _exact(stripped, lang)
    if hit is not None:
        lead = src[:len(src) - len(src.lstrip())]
        trail = src[len(src.rstrip()):]
        out = lead + hit + trail
    else:
        shielded, saved = _shield(src)
        rx, table = _compile(lang)
        out = rx.sub(lambda m: table[m.group(0)], shielded) if rx is not None else shielded
        out = _glossary(out, lang)
        out = _restore(out, saved)
    if lang in _ORD:
        out = re.sub(r"(\d+)(?:st|nd|rd|th)\b", lambda m, suf=_ORD[lang]: m.group(1) + suf, out)
    if out == _norm(_unescape(original)):
        return original
    return out

def client_pack(lang: str) -> dict:
    keys = ["Vedic time since sunrise", "ghati", "pala", "vipala", "Use my location", "Search your city",
            "Using your timezone…", "Location permission was blocked. Type a city or town.",
            "No place found. Try another spelling.", "Search failed. Try again.",
            "Waiting for location permission…", "Asking permission…"]
    if lang not in LANGS:
        return {}
    return {k: P[k][lang] for k in keys}

def _load_saved_json():
    """Load the saved word book and full-sentence book from data/."""
    import json, os
    root = os.path.normpath(os.path.join(os.path.dirname(__file__), "..", "..", "data"))
    for name in ("words_1.json", "words_2.json", "words_3.json", "sentences.json"):
        path = os.path.join(root, name)
        if not os.path.isfile(path):
            continue
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        for en, eight in data.items():
            if isinstance(eight, (list, tuple)) and len(eight) == 8 and en:
                add(en, *eight)

def _load_phrases():
    from .prose_i18n import seed
    seed(add)
    from .saved_lexicon import pairs
    for en, eight in pairs():
        add(en, *eight)
    _load_saved_json()
    _BUILT.clear()

_load_phrases()
